window.bookSummaryJSON = "<p><i>The Horror at Oakdeene and Others</i> is another of Brian Lumley's collections of short stories, with many of them involving the Cthulhu Mythos. </p> <p>Stories included in this collection: </p> <p>\"The Viking's Stone\" <br> \"Aunt Hester\" <br> \"No Way Home\" <br> \"The Horror at Oakdeene\" <br> \"The Cleaner Woman\" <br> \"The Statement of Henry Worthy\" <br> \"Darghud's Doll\" <br> \"Born of the Winds\"</p>"; 
